class Solution {
public:
    int bestClosingTime(string customers) {
        int n = customers.size();
        int totalY = 0;
        for (char c : customers) {
            if (c == 'Y') totalY++;
        }
        int minPenalty = totalY;
        int bestHour = 0;
        int penalty = totalY;
        for (int j = 0; j < n; j++) {
            if (customers[j] == 'Y') {
                penalty--;
            } else {
                penalty++;
            }
            if (penalty < minPenalty) {
                minPenalty = penalty;
                bestHour = j + 1;
            }
        }
        return bestHour;
    }
};
